from collections import deque
def f(g,bg,fill):
    h,w=len(g),len(g[0]); out=[r[:] for r in g]
    # flood from border; enclosed bg -> 4
    seen=set(); q=deque()
    for c in range(w):
        for r in (0,h-1):
            if g[r][c]==bg and (r,c) not in seen: seen.add((r,c)); q.append((r,c))
    for r in range(h):
        for c in (0,w-1):
            if g[r][c]==bg and (r,c) not in seen: seen.add((r,c)); q.append((r,c))
    while q:
        y,x=q.popleft()
        for dy,dx in((-1,0),(1,0),(0,-1),(0,1)):
            ny,nx=y+dy,x+dx
            if 0<=ny<h and 0<=nx<w and g[ny][nx]==bg and (ny,nx) not in seen:
                seen.add((ny,nx)); q.append((ny,nx))
    for r in range(h):
        for c in range(w):
            if g[r][c]==bg and (r,c) not in seen: out[r][c]=fill
    # find opening: contiguous bg run on bbox top row spanning >=1 cell; its column range = beam
    pts=[(r,c) for r in range(h) for c in range(w) if g[r][c]!=bg]
    r0=min(p[0] for p in pts); c0=min(p[1] for p in pts)
    r1=max(p[0] for p in pts); c1=max(p[1] for p in pts)
    runs=[]; s=None
    for c in range(c0,c1+1):
        if g[r0][c]==bg:
            if s is None: s=c
        else:
            if s is not None: runs.append((s,c-1)); s=None
    if s is not None: runs.append((s,c1))
    s,e=runs[0]
    # vertical beam through gap columns up to top edge
    for c in range(s,e+1):
        for r in range(r0):
            out[r][c]=fill
    # diagonal rays from gap corner columns
    if s>e: pass
    for c in (s,e):
        for r in range(r0-1,-1,-1):
            cc=c+(r0-r)
            if 0<=cc<w: out[r][cc]=fill
    return out
