def f(g,bg,fill=4):
    h,w=len(g),len(g[0]); out=[r[:] for r in g]
    # enclosed cavity: bg not reachable from border (4-conn)
    seen=set(); q=deque()
    for c in range(w):
        for r_ in (0,h-1):
            if g[r_][c]==bg and (r_,c) not in seen: seen.add((r_,c)); q.append((r_,c))
    for r_ in range(h):
        for c in (0,w-1):
            if g[r_][c]==bg and (r_,c) not in seen: seen.add((r_,c)); q.append((r_,c))
    while q:
        y,x=q.popleft()
        for dy,dx in((-1,0),(1,0),(0,-1),(0,1)):
            ny,nx=y+dy,x+dx
            if 0<=ny<h and 0<=nx<w and g[ny][nx]==bg and (ny,nx) not in seen:
                seen.add((ny,nx)); q.append((ny,nx))
    cav={(r_,c) for r_ in range(h) for c in range(w) if g[r_][c]==bg and (r_,c) not in seen}
    for r_,c in cav: out[r_][c]=fill
    # gap = contiguous bg run on bbox top row, excluding cells that would connect cavity to outside
    pts=[(r_,c) for r_ in range(h) for c in range(w) if g[r_][c]!=bg]
    r0=min(p[0] for p in pts); c0=min(p[1] for p in pts); r1=max(p[0] for p in pts); c1=max(p[1] for p in pts)
    gap_start=None
    for c_ in range(c0,c1+1):
        if g[r0][c_]==bg:
            # safe if sealing gap isolates cavity
            if gap_start is None: gap_start=c_
            else: break
    gap_end=None
    for c_ in range(c1,c0-1,-1):
        if g[r0][c_]==bg:
            if gap_end is None: gap_end=c_
            else: break
    if gap_start is not None and gap_end is not None and gap_start<=gap_end:
        sg,sge=gap_start,gap_end
        # corridor: straight up from gap to border
        for c_ in range(sg,sge+1):
            for r_ in range(r0-1,-1,-1):
                out[r_][c_]=fill
        # diverging rays from gap endpoints upward
        for c_ in (sg,sge):
            for r_ in range(r0-1,-1,-1):
                cc=c_+(r0-r_)
                if 0<=cc<w: out[r_][cc]=fill
    return out
