t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
for m in re.finditer(r'(Demo pair (\w+) \((\d+)x(\d+)\):\n',t):
    lab=m[1]; n=int(m[2]); hh,ww=int(m[3]),int(m[4])
    rows=[r.split() for r in t[m.end():].split('\n')[:hh]]
    if all(len(r)==ww and all(x.isdigit() for x in r) for r in rows):
        key='i' if 'input' in lab else 'o'
        G.setdefault(n,{}).setdefault(key,[[int(x) for x in r] for r in rows])
print(sorted(G))
def solve(g,bg):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; q=collections.deque()
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]==bg and not seen[i][j]: seen[i][j]=True; q.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]==bg and not seen[i][j]: seen[i][j]=True; q.append((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and not seen[ni][nj] and g[ni][nj]==bg:
                seen[ni][nj]=True;q.append((ni,nj))
    out=[row[:] for row in g]
    for i in range(h):
        for j in range(w):
            if g[i][j]==bg and not seen[i][j]: out[i][j]=4
    return out
res=[]
for n in sorted(G):
    inp,out=G[n]['i'],G[n]['o']
    res.append((n,solve(inp,int(inp[0][0]))==out))
print(res)

